import React, { useState, useMemo } from 'react';
import {
  Box,
  Button,
  Container,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  IconButton,
  TablePagination,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  TextField,
  Snackbar,
  Alert,
} from '@mui/material';
import { Edit, Delete, Visibility } from '@mui/icons-material';

// --- Initial Data based on the provided JSON ---
const initialRows = [
  {
    "Subject Code": "EXPL001",
    "Subject Name": "Example 1",
    "Term": "Spring",
    "Subject Coordinator": "Tom",
    "Version": "1",
    "Date": "18/11/24",
    "Format of delivery": "Lecture based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
  {
    "Subject Code": "EXPL002",
    "Subject Name": "Example 2",
    "Term": "Autumn",
    "Subject Coordinator": "Usha",
    "Version": "1",
    "Date": "25/08/24",
    "Format of delivery": "Project based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
  {
    "Subject Code": "EXPL003",
    "Subject Name": "Example 3",
    "Term": "1H",
    "Subject Coordinator": "Victoria",
    "Version": "1",
    "Date": "08/04/24",
    "Format of delivery": "Lecture based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
    {
    "Subject Code": "EXPL004",
    "Subject Name": "Example 4",
    "Term": "2H",
    "Subject Coordinator": "Fred",
    "Version": "1",
    "Date": "21/07/24",
    "Format of delivery": "Project based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
  {
    "Subject Code": "EXPL005",
    "Subject Name": "Example 5",
    "Term": "Q1",
    "Subject Coordinator": "Ian",
    "Version": "1",
    "Date": "05/03/24",
    "Format of delivery": "Lecture based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
    {
    "Subject Code": "EXPL006",
    "Subject Name": "Example 6",
    "Term": "Q2",
    "Subject Coordinator": "Jane",
    "Version": "1",
    "Date": "18/11/24",
    "Format of delivery": "Lecture based",
    "Total Subject Workload": "51.5%",
    "Total Workload Allocation": "51.5%",
    "Unallocated Available Workload": "0",
  },
];

const columns = [
  "Subject Code", "Subject Name", "Term", "Subject Coordinator", "Version", "Date",
  "Format of delivery", "Total Subject Workload", "Total Workload Allocation",
  "Unallocated Available Workload", "Action"
];

const App = () => {
  // --- State Management ---
  const [subjects, setSubjects] = useState(initialRows);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [currentSubject, setCurrentSubject] = useState(null);
  const [newSubjectData, setNewSubjectData] = useState({});
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // --- Utility Functions ---
  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  // --- Dialog Handlers ---
  const handleOpenAddDialog = () => {
    setNewSubjectData({}); // Clear form for new entry
    setOpenAddDialog(true);
  };

  const handleOpenEditDialog = (subject) => {
    setCurrentSubject(subject);
    setNewSubjectData(subject); // Pre-fill form with existing data
    setOpenEditDialog(true);
  };

  const handleOpenDeleteDialog = (subject) => {
    setCurrentSubject(subject);
    setOpenDeleteDialog(true);
  };

  const handleCloseDialogs = () => {
    setOpenAddDialog(false);
    setOpenEditDialog(false);
    setOpenDeleteDialog(false);
    setCurrentSubject(null);
  };

  // --- CRUD Operations ---
  const handleAddSubject = () => {
    const newSubject = {
      ...newSubjectData,
      "Total Subject Workload": "0%", // Default values
      "Total Workload Allocation": "0%",
      "Unallocated Available Workload": "0"
    };
    setSubjects([newSubject, ...subjects]);
    handleCloseDialogs();
    showSnackbar("Subject added successfully!");
  };

  const handleUpdateSubject = () => {
    setSubjects(subjects.map(sub =>
      sub["Subject Code"] === currentSubject["Subject Code"] ? { ...sub, ...newSubjectData } : sub
    ));
    handleCloseDialogs();
    showSnackbar("Subject updated successfully!");
  };

  const handleDeleteSubject = () => {
    setSubjects(subjects.filter(sub => sub["Subject Code"] !== currentSubject["Subject Code"]));
    handleCloseDialogs();
    showSnackbar("Subject deleted successfully!", "error");
  };

  // --- Navigation & Table Handlers ---
  const handleNavigate = (subjectName) => {
    showSnackbar(`Navigating to workload page for ${subjectName}`, 'info');
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleFormChange = (event) => {
    const { name, value } = event.target;
    setNewSubjectData(prev => ({ ...prev, [name]: value }));
  };

  // --- Memoized Data for Performance ---
  const paginatedSubjects = useMemo(() =>
    subjects.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [subjects, page, rowsPerPage]
  );

  // --- Reusable Form Fields Component ---
  const SubjectForm = () => (
    <>
      <TextField margin="dense" name="Subject Code" label="Subject Code" type="text" fullWidth variant="outlined" value={newSubjectData["Subject Code"] || ''} onChange={handleFormChange} disabled={openEditDialog} />
      <TextField margin="dense" name="Subject Name" label="Subject Name" type="text" fullWidth variant="outlined" value={newSubjectData["Subject Name"] || ''} onChange={handleFormChange} />
      <TextField margin="dense" name="Term" label="Term" type="text" fullWidth variant="outlined" value={newSubjectData["Term"] || ''} onChange={handleFormChange} />
      <TextField margin="dense" name="Subject Coordinator" label="Subject Coordinator" type="text" fullWidth variant="outlined" value={newSubjectData["Subject Coordinator"] || ''} onChange={handleFormChange} />
      <TextField margin="dense" name="Version" label="Version" type="text" fullWidth variant="outlined" value={newSubjectData["Version"] || ''} onChange={handleFormChange} />
      <TextField margin="dense" name="Date" label="Date" type="text" fullWidth variant="outlined" value={newSubjectData["Date"] || ''} onChange={handleFormChange} placeholder="DD/MM/YY" />
      <TextField margin="dense" name="Format of delivery" label="Format of delivery" type="text" fullWidth variant="outlined" value={newSubjectData["Format of delivery"] || ''} onChange={handleFormChange} />
    </>
  );

  return (
    <Container maxWidth="xl" sx={{ py: 4, backgroundColor: '#f4f6f8', minHeight: '100vh' }}>
      <Paper sx={{ p: 2, borderRadius: '12px', boxShadow: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h5" component="h1" fontWeight="bold">
            Subject Management
          </Typography>
          <Button
            id="btn_add_subject"
            variant="contained"
            onClick={handleOpenAddDialog}
            sx={{ backgroundColor: 'black', '&:hover': { backgroundColor: '#333' } }}
          >
            Add Subject
          </Button>
        </Box>

        <TableContainer>
          <Table sx={{ minWidth: 650 }} aria-label="subject table">
            <TableHead sx={{ backgroundColor: '#fafafa' }}>
              <TableRow>
                {columns.map((column) => (
                  <TableCell key={column} sx={{ fontWeight: 'bold' }}>{column}</TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedSubjects.map((row, index) => (
                <TableRow
                  key={index}
                  hover
                  sx={{ '&:last-child td, &:last-child th': { border: 0 }, cursor: 'pointer' }}
                >
                  {columns.map((column) => (
                    <TableCell
                      key={column}
                      onClick={() => column !== 'Action' && handleNavigate(row['Subject Name'])}
                    >
                      {column === "Action" ? (
                        <Box sx={{ display: 'flex' }}>
                           <IconButton onClick={(e) => { e.stopPropagation(); handleNavigate(row['Subject Name']); }} size="small" aria-label="view">
                            <Visibility />
                          </IconButton>
                          <IconButton onClick={(e) => { e.stopPropagation(); handleOpenEditDialog(row); }} size="small" aria-label="edit">
                            <Edit />
                          </IconButton>
                          <IconButton onClick={(e) => { e.stopPropagation(); handleOpenDeleteDialog(row); }} size="small" aria-label="delete">
                            <Delete />
                          </IconButton>
                        </Box>
                      ) : (
                        row[column]
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          rowsPerPageOptions={[10, 25, 50]}
          component="div"
          count={subjects.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </Paper>

      {/* Add/Edit Dialog */}
      <Dialog open={openAddDialog || openEditDialog} onClose={handleCloseDialogs}>
        <DialogTitle>{openAddDialog ? 'Add New Subject' : 'Update Subject'}</DialogTitle>
        <DialogContent>
          <SubjectForm />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialogs}>Cancel</Button>
          <Button onClick={openAddDialog ? handleAddSubject : handleUpdateSubject}>Submit</Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={openDeleteDialog} onClose={handleCloseDialogs}>
        <DialogTitle>Confirm Deletion</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Are you sure you want to delete the subject "{currentSubject?.['Subject Name']}"? This action cannot be undone.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialogs}>Cancel</Button>
          <Button onClick={handleDeleteSubject} color="error">Confirm</Button>
        </DialogActions>
      </Dialog>

      {/* Notification Snackbar */}
      <Snackbar open={snackbar.open} autoHideDuration={4000} onClose={handleCloseSnackbar} anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}>
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default App;
